#include "rules/frozen_ball_declaration.h"
namespace billiardgl::rules { namespace {
RefereeAuthorityConsumerPolicy policy(){RefereeAuthorityConsumerPolicy p;p.declarationKind=kFrozenCueObjectDeclarationKind;p.allowedActorRoles={RefereeAuthorityRole::Referee};p.proposalPayloadKeyTypes={{"cue_ball_id",RefereeAuthorityPayloadType::Number},{"frozen_attested",RefereeAuthorityPayloadType::Bool},{"object_ball_id",RefereeAuthorityPayloadType::Number},{"relation",RefereeAuthorityPayloadType::String}};p.finalPayloadKeyTypes={{"cue_ball_id",RefereeAuthorityPayloadType::Number},{"frozen_attested",RefereeAuthorityPayloadType::Bool},{"object_ball_id",RefereeAuthorityPayloadType::Number},{"proposal_decision_id",RefereeAuthorityPayloadType::String},{"relation",RefereeAuthorityPayloadType::String}};p.cancelPayloadKeyTypes={{"proposal_decision_id",RefereeAuthorityPayloadType::String}};p.finalPayloadMayDifferFromProposal=true;p.cancelPayloadMayDifferFromProposal=true;p.maxPayloadBytes=1024;p.maxLifetimeTicks=100000;p.proposalRequired=true;p.sameActorCancelRequired=true;return p;}
FrozenBallDeclarationResult reject(const std::string&c){FrozenBallDeclarationResult r;r.errorCode=c;return r;}
std::string proposalPayload(int object){return std::string("{\"cue_ball_id\":0,\"frozen_attested\":true,\"object_ball_id\":")+std::to_string(object)+",\"relation\":\"CUE_BALL_FROZEN_TO_LEGAL_OBJECT_BALL\"}";}
std::string finalPayload(int object,const std::string&id){return std::string("{\"cue_ball_id\":0,\"frozen_attested\":true,\"object_ball_id\":")+std::to_string(object)+",\"proposal_decision_id\":\""+id+"\",\"relation\":\"CUE_BALL_FROZEN_TO_LEGAL_OBJECT_BALL\"}";}
std::string cancelPayload(const std::string&id){return std::string("{\"proposal_decision_id\":\"")+id+"\"}";}
bool valid(const FrozenBallDeclarationContext&c){return c.cueBallId==0&&c.objectBallId>=1&&c.objectBallId<=15&&!c.parentStateHash.empty();}
}
FrozenBallDeclarationAuthority::FrozenBallDeclarationAuthority(const RefereeAuthorityAuthenticator*a,const RefereeAuthorityCommitGuard*g):protocol_({policy()},a,g){}
void FrozenBallDeclarationAuthority::reset(const std::string&r){protocol_.reset(r);state_=FrozenBallDeclarationState{};state_.rackIdentity=r;}
FrozenBallDeclarationResult FrozenBallDeclarationAuthority::propose(const RefereeAuthorityRequest&r,const FrozenBallDeclarationContext&c,std::uint64_t t){if(state_.phase!=FrozenBallDeclarationPhase::Inactive&&state_.phase!=FrozenBallDeclarationPhase::ProposalOpen)return reject("frozen_declaration_state");if(!valid(c)||r.payloadCanonical!=proposalPayload(c.objectBallId))return reject("frozen_declaration_context");auto v=protocol_.submit(r,t);if(!v.ok)return reject(v.errorCode);if(state_.phase==FrozenBallDeclarationPhase::Inactive){state_.phase=FrozenBallDeclarationPhase::ProposalOpen;state_.context=c;state_.proposalDecisionId=r.decisionId;state_.refereeSubjectId=r.authoritySubjectId;state_.proposalPayloadSha256=refereeAuthoritySha256Hex(r.payloadCanonical);}return {true,"",v.ack};}
FrozenBallDeclarationResult FrozenBallDeclarationAuthority::finalDeclare(const RefereeAuthorityRequest&r,const FrozenBallDeclarationContext&c,std::uint64_t t){if(state_.phase!=FrozenBallDeclarationPhase::ProposalOpen&&state_.phase!=FrozenBallDeclarationPhase::Active&&state_.phase!=FrozenBallDeclarationPhase::Consumed)return reject("frozen_declaration_final_state");if(c.cueBallId!=state_.context.cueBallId||c.objectBallId!=state_.context.objectBallId||c.parentRevision!=state_.context.parentRevision||c.parentStateHash!=state_.context.parentStateHash||r.authoritySubjectId!=state_.refereeSubjectId||r.payloadCanonical!=finalPayload(c.objectBallId,state_.proposalDecisionId))return reject("frozen_declaration_final_context");const auto previous=state_.phase;auto v=protocol_.submit(r,t);if(!v.ok)return reject(v.errorCode);if(previous==FrozenBallDeclarationPhase::ProposalOpen){state_.phase=FrozenBallDeclarationPhase::Active;state_.committed=true;state_.finalPayloadSha256=refereeAuthoritySha256Hex(r.payloadCanonical);}return {true,"",v.ack};}
FrozenBallDeclarationResult FrozenBallDeclarationAuthority::cancel(const RefereeAuthorityRequest&r,std::uint64_t t){if((state_.phase!=FrozenBallDeclarationPhase::ProposalOpen&&state_.phase!=FrozenBallDeclarationPhase::Cancelled)||r.authoritySubjectId!=state_.refereeSubjectId||r.payloadCanonical!=cancelPayload(state_.proposalDecisionId))return reject("frozen_declaration_cancel_context");const auto previous=state_.phase;auto v=protocol_.submit(r,t);if(!v.ok)return reject(v.errorCode);if(previous==FrozenBallDeclarationPhase::ProposalOpen)state_.phase=FrozenBallDeclarationPhase::Cancelled;return {true,"",v.ack};}
bool FrozenBallDeclarationAuthority::consume(const std::string&s,std::uint64_t t){if(state_.phase!=FrozenBallDeclarationPhase::Active||!state_.committed||s.empty())return false;state_.phase=FrozenBallDeclarationPhase::Consumed;state_.consumedShotIdentity=s;state_.consumedAuthorityTick=t;return true;}
void FrozenBallDeclarationAuthority::invalidate(){if(state_.phase!=FrozenBallDeclarationPhase::Consumed&&state_.phase!=FrozenBallDeclarationPhase::Cancelled)state_.phase=FrozenBallDeclarationPhase::Invalidated;state_.committed=false;}
void FrozenBallDeclarationAuthority::restoreCommittedForReplay(
    const std::string&r,const FrozenBallDeclarationContext&c,
    const std::string&proposalId,const std::string&subject){
    reset(r);state_.phase=FrozenBallDeclarationPhase::Active;state_.context=c;
    state_.proposalDecisionId=proposalId;state_.refereeSubjectId=subject;
    state_.proposalPayloadSha256=refereeAuthoritySha256Hex(
        proposalPayload(c.objectBallId));
    state_.finalPayloadSha256=refereeAuthoritySha256Hex(
        finalPayload(c.objectBallId,proposalId));state_.committed=true;}
}
